//! Independent consumer verification returns the bytes actually admitted.
use super::super::{
    AssetKind, AssetRecord, Digest, EmbeddedModuleInventory, MANIFEST_LIMIT, MODULE_LIMIT,
    inventory::invalid, source,
};
use super::{FileIdentity, LocalBindings, VerificationContext, admission, lock, verification};
use std::{
    io,
    path::{Path, PathBuf},
};

/// Generated bytes verified against an admitted inventory record.
#[derive(Debug)]
pub struct VerifiedAsset {
    record: AssetRecord,
    bytes: Vec<u8>,
    source_path: PathBuf,
}
impl VerifiedAsset {
    /// Borrows the canonical asset record.
    #[must_use]
    pub const fn record(&self) -> &AssetRecord {
        &self.record
    }
    /// Borrows the exact independently verified bytes for `OUT_DIR` copying.
    #[must_use]
    pub fn bytes(&self) -> &[u8] {
        &self.bytes
    }
    /// Borrows the admitted local source path for rerun tracking.
    #[must_use]
    pub fn source_path(&self) -> &Path {
        &self.source_path
    }
}
/// Verified local preparation with all bytes retained before embedding.
///
/// SHA-256 identities provide integrity under the collision-resistance assumption.
/// Admission checks current declared inputs, not proof of tool execution or a
/// complete installed-toolchain image. In particular, three executable identities
/// do not attest rustc's separately installed driver libraries or sysroot archives.
#[derive(Debug)]
pub struct PreparedModule {
    inventory: EmbeddedModuleInventory,
    inventory_digest: Digest,
    inventory_bytes: Vec<u8>,
    assets: [VerifiedAsset; 2],
    rerun_paths: Vec<PathBuf>,
}
impl PreparedModule {
    /// Opens the inventory and local sidecar, checks current locked sources,
    /// tools/configuration and every recorded input, then retains verified assets.
    /// Producer context also compares current effective WASM environment values;
    /// native context consumes the inventory's typed WASM configuration without
    /// reinterpreting native Cargo's derived environment as module configuration.
    ///
    /// # Errors
    /// Missing, linked, stale, malformed, mismatched or oversized preparation
    /// fails with contextual cause. No prior or empty asset is substituted.
    #[inline]
    pub fn open<C: VerificationContext>(
        inventory_path: &Path,
        workspace_root: &Path,
        cargo_home: &Path,
        _context: C,
    ) -> io::Result<Self> {
        let _span =
            tracing::info_span!("verify_prepared_module", inventory = %inventory_path.display())
                .entered();
        let mut admitted = Admission::read(inventory_path, workspace_root, cargo_home)?;
        verification::bound_tools(
            &admitted.inventory,
            &admitted.bindings,
            &admitted.workspace,
            &mut admitted.rerun_paths,
        )?;
        // Sealed ZST policy makes this branch a compile-time ownership decision.
        if C::PRODUCER_ENVIRONMENT {
            verification::producer_configuration(
                &admitted.inventory,
                &admitted.bindings,
                &admitted.workspace,
                &admitted.cargo_home,
            )?;
        }
        admitted.retain()
    }
    /// Borrows the admitted semantic inventory.
    #[must_use]
    pub const fn inventory(&self) -> &EmbeddedModuleInventory {
        &self.inventory
    }
    /// Borrows the exact independently admitted canonical inventory bytes.
    #[must_use]
    pub fn inventory_bytes(&self) -> &[u8] {
        &self.inventory_bytes
    }
    /// Borrows exactly the admitted JavaScript and WASM bytes.
    #[must_use]
    pub const fn assets(&self) -> &[VerifiedAsset; 2] {
        &self.assets
    }
    /// Returns SHA-256 of the canonical admitted inventory bytes.
    #[must_use]
    pub const fn inventory_digest(&self) -> Digest {
        self.inventory_digest
    }
    /// Files the consumer must declare as Cargo rerun inputs.
    #[must_use]
    pub fn rerun_paths(&self) -> &[PathBuf] {
        &self.rerun_paths
    }
}

// Type-independent IO phases remain single compiled bodies for both policies.
struct Admission {
    workspace: PathBuf,
    cargo_home: PathBuf,
    directory: PathBuf,
    inventory: EmbeddedModuleInventory,
    inventory_digest: Digest,
    inventory_bytes: Vec<u8>,
    bindings: LocalBindings,
    rerun_paths: Vec<PathBuf>,
}
impl Admission {
    fn read(inventory_path: &Path, workspace_root: &Path, cargo_home: &Path) -> io::Result<Self> {
        let workspace = super::canonical_directory(workspace_root)?;
        let cargo_home = super::canonical_directory(cargo_home)?;
        let inventory_path = super::canonical_file(inventory_path)?;
        let directory = inventory_path
            .parent()
            .ok_or_else(|| invalid("inventory path has no owner directory"))?
            .to_path_buf();
        super::canonical_directory(&directory)?;
        let inventory_file = FileIdentity::read(&inventory_path, MANIFEST_LIMIT)?;
        let inventory_bytes = inventory_file.verified_bytes(&inventory_path, MANIFEST_LIMIT)?;
        let inventory = EmbeddedModuleInventory::decode(&inventory_bytes)?;
        tracing::info!(
            providers = inventory.spec().providers.len(),
            compiler_inputs = inventory.spec().inputs.len(),
            directories = inventory.spec().directories.len(),
            "bounded inventory admitted"
        );
        let inventory_digest = Digest::hash(&inventory_bytes);
        let binding_path = source(&directory, LocalBindings::FILE_NAME)?;
        let binding_file = FileIdentity::read(&binding_path, MANIFEST_LIMIT)?;
        let bindings =
            LocalBindings::decode(&binding_file.verified_bytes(&binding_path, MANIFEST_LIMIT)?)?;
        admission::owners(&inventory, &bindings.owners, &workspace, &cargo_home)?;
        let lock_path = source(&workspace, "Cargo.lock")?;
        let lock_identity = FileIdentity::read(&lock_path, MANIFEST_LIMIT)?;
        if lock_identity.digest != inventory.spec().lock_digest {
            return Err(invalid("prepared Cargo.lock digest is stale"));
        }
        lock::providers(
            &inventory,
            &lock_identity.verified_bytes(&lock_path, MANIFEST_LIMIT)?,
        )?;
        let rerun_paths = vec![inventory_path, binding_path, lock_path];
        Ok(Self {
            workspace,
            cargo_home,
            directory,
            inventory,
            inventory_digest,
            inventory_bytes,
            bindings,
            rerun_paths,
        })
    }
    fn retain(mut self) -> io::Result<PreparedModule> {
        let verified_inputs = verification::inputs(
            &self.inventory,
            &self.bindings,
            &self.workspace,
            &self.cargo_home,
            &mut self.rerun_paths,
        )?;
        verification::directories(
            &self.inventory,
            &self.bindings,
            &verified_inputs,
            &mut self.rerun_paths,
        )?;
        let mut assets = Vec::with_capacity(2);
        for record in &self.inventory.spec().assets {
            let path = source(&self.directory, &record.destination)?;
            let bytes = record.identity.verified_bytes(&path, MODULE_LIMIT)?;
            if record.kind == AssetKind::WebAssembly {
                super::module::function_export(&bytes, &self.inventory.spec().module.export)?;
            }
            self.rerun_paths.push(path.clone());
            assets.push(VerifiedAsset {
                record: record.clone(),
                bytes,
                source_path: path,
            });
        }
        self.rerun_paths.sort();
        self.rerun_paths.dedup();
        Ok(PreparedModule {
            inventory: self.inventory,
            inventory_digest: self.inventory_digest,
            inventory_bytes: self.inventory_bytes,
            assets: assets
                .try_into()
                .map_err(|_| invalid("verified asset count differs from two"))?,
            rerun_paths: self.rerun_paths,
        })
    }
}
